import { Suspense } from 'react'
import { prefetch } from 'next/cache'
import { getRelatedProducts } from '@/lib/data'

export default function ProductPage() {
  return (
    <main>
      <h1>Premium Widget</h1>
      <p>A durable widget for everyday projects.</p>
      <section>
        <h2>Related products</h2>
        <Suspense fallback={<p>Loading related products…</p>}>
          {/* The fallback is in the App Shell; the products are not.
              They render on a per-link prefetch (<Link prefetch>) or on
              navigation, so they stay out of the default prefetch. */}
          <RelatedProducts />
        </Suspense>
      </section>
    </main>
  )
}

async function RelatedProducts() {
  // Keep related products out of the App Shell that every link into this
  // route prefetches by default. A <Link prefetch> resolves them ahead of
  // the click, so they are ready immediately on navigation.
  await prefetch()
  const relatedProducts = await getRelatedProducts()
  return (
    <ul>
      {relatedProducts.map((product) => (
        <li key={product}>{product}</li>
      ))}
    </ul>
  )
}

